import subprocess,json,urllib.request,base64,time,decimal,hashlib
pid=subprocess.check_output(['systemctl','show','proofofwork-api','-p','MainPID','--value'],text=True).strip()
env=dict(e.split('=',1) for e in open('/proc/'+pid+'/environ').read().split('\0') if '=' in e)
url=env['BITCOIN_RPC_URL'];auth=base64.b64encode((env['BITCOIN_RPC_USER']+':'+env['BITCOIN_RPC_PASSWORD']).encode()).decode()
def rpc(batch):
 q=urllib.request.Request(url,json.dumps([{'jsonrpc':'2.0','id':i,'method':m,'params':p} for i,(m,p) in enumerate(batch)]).encode(),{'Authorization':'Basic '+auth,'Content-Type':'application/json'})
 x=json.load(urllib.request.urlopen(q,timeout=90),parse_float=decimal.Decimal);return sorted(x,key=lambda v:v['id'])
def sql(q):
 r=subprocess.check_output(['sudo','-u','postgres','psql','-XAt','-d','proof_indexer','-c',q],text=True);return [json.loads(s) for s in r.splitlines()]
r={};before=rpc([('getblockchaininfo',[]),('getrawmempool',[]) ]);r['tipBefore']=before[0]['result']['blocks'];mp=set(before[1]['result']);r['mempoolCountBefore']=len(mp)
rows=sql("SELECT json_build_object('txid',txid,'status',status,'blockhash',block_hash,'height',block_height,'raw',raw_tx->>'hex') FROM proof_indexer.transactions WHERE network='livenet' ORDER BY txid")
r['transactionsChecked']=len(rows);r['errors']=[];r['pendingAbsent']=[];r['droppedPresent']=[]
for off in range(0,len(rows),50):
 chunk=rows[off:off+50];results=rpc([('getrawtransaction',[v['txid'],True]) for v in chunk])
 for v,a in zip(chunk,results):
  z=a.get('result');err=a.get('error');st=v['status']
  if st=='confirmed' and (not z or z.get('blockhash')!=v['blockhash'] or z.get('confirmations',0)<=0):r['errors'].append({'txid':v['txid'],'kind':'canonical-confirmation','rpcCode':err.get('code') if err else None})
  if z and v['raw'] and v['raw']!=z['hex']:r['errors'].append({'txid':v['txid'],'kind':'raw-hex'})
  if st=='pending' and v['txid'] not in mp:r['pendingAbsent'].append(v['txid'])
  if st=='dropped' and v['txid'] in mp:r['droppedPresent'].append(v['txid'])
 if off%2500==0:print('PROGRESS',off,flush=True)
 # bounded sequential RPC groups, no parallel pressure
 time.sleep(.02)
blocks=sql("SELECT json_build_object('height',height,'hash',block_hash) FROM proof_indexer.blocks WHERE network='livenet' AND canonical ORDER BY height")
r['canonicalBlocksChecked']=len(blocks);r['blockHashErrors']=[]
for off in range(0,len(blocks),100):
 c=blocks[off:off+100]
 for v,a in zip(c,rpc([('getblockhash',[v['height']]) for v in c])):
  if a.get('result')!=v['hash']:r['blockHashErrors'].append(v)
files=sql("SELECT json_build_object('txid',txid,'size',size_bytes,'sha',sha256,'bytes',encode(content_bytes,'base64')) FROM proof_indexer.file_attachments")
r['attachmentsChecked']=len(files);r['attachmentErrors']=[]
for f in files:
 b=base64.b64decode(f['bytes']) if f['bytes'] is not None else None
 if b is not None and (len(b)!=f['size'] or hashlib.sha256(b).hexdigest()!=f['sha']):r['attachmentErrors'].append(f['txid'])
after=rpc([('getblockchaininfo',[]),('getrawmempool',[])]);mp2=set(after[1]['result']);r['tipAfter']=after[0]['result']['blocks'];r['pendingAbsentBoth']=[t for t in r['pendingAbsent'] if t not in mp2];r['droppedPresentBoth']=[t for t in r['droppedPresent'] if t in mp2]
print(json.dumps(r,indent=2),flush=True)

